import { $ } from 'bun';
import { mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import type { AgentConfig, Arm, ContainerInfo } from './types.js';

/**
 * Formats an error thrown by Bun.$ — appends captured stderr when present.
 */
function errorDetail(error: unknown): string {
  if (error instanceof Error) {
    const stderr = (error as Error & { stderr?: Buffer }).stderr
      ?.toString()
      .trim();
    return stderr ? `${error.message}: ${stderr}` : error.message;
  }
  return String(error);
}

export class ContainerManager {
  /**
   * Launches a container for the given agent configuration.
   * The container runs autonomously -- this method does NOT wait for it to finish.
   */
  async launchAgent(
    agentConfig: AgentConfig,
    dockerImage: string,
    resultsDir: string,
  ): Promise<ContainerInfo> {
    const imageTag = `${dockerImage}:${agentConfig.arm}`;
    const memoryType =
      agentConfig.arm === 'claude-mem' ? 'claude-mem' : 'vanilla';

    const promptFilePath = resolve(agentConfig.prompt.filePath);
    const absoluteResultsDir = resolve(resultsDir);

    // Each agent gets its own results subdirectory, not the shared
    // --results-dir root. aggregator.ts's aggregateAll (and report.ts's
    // fillMissingResults) scan resultsDir for one subdirectory PER AGENT --
    // a flat mount of resultsDir itself produces zero agent directories
    // (empty report) and, with 2+ concurrent containers, races multiple
    // entrypoint.sh writers onto the same host transcript/stderr/exit-code
    // files. entrypoint.sh needs no change: it already writes relative to
    // the fixed /workspace/results mount point, so giving each container a
    // private per-agent mount there is sufficient.
    const agentResultsDir = resolve(absoluteResultsDir, agentConfig.agentId);
    await mkdir(agentResultsDir, { recursive: true });

    // Claude Code -> OpenRouter routing recipe (spawn agent-setup.ts:1207-1209;
    // Claude Code llm-gateway-connect docs). BASE_URL has no /v1 -- Claude Code
    // appends /v1/messages itself. API_KEY must be explicitly EMPTY (not unset)
    // so Claude Code cannot fall back to Anthropic direct; auth is Bearer via
    // AUTH_TOKEN only. The CUSTOM_HEADERS value contains a real newline between
    // the two headers (docker -e passes it intact; verified).
    const runArgs = [
      'run',
      '-d',
      '--network',
      'bridge',
      '-e',
      'ANTHROPIC_BASE_URL=https://openrouter.ai/api',
      '-e',
      `ANTHROPIC_AUTH_TOKEN=${agentConfig.apiKey}`,
      '-e',
      'ANTHROPIC_API_KEY=',
      '-e',
      `ANTHROPIC_MODEL=${agentConfig.modelVersion}`,
      '-e',
      'ANTHROPIC_DEFAULT_HAIKU_MODEL=anthropic/claude-haiku-4.5',
      '-e',
      'ANTHROPIC_CUSTOM_HEADERS=HTTP-Referer: https://github.com/thedotmack/ArenaBench\nX-OpenRouter-Title: ArenaBench',
      '-e',
      'CLAUDE_CODE_SKIP_ONBOARDING=1',
      '-e',
      'CLAUDE_CODE_ENABLE_TELEMETRY=0',
      '-e',
      'DISABLE_AUTOUPDATER=1',
      '-e',
      `AGENT_ID=${agentConfig.agentId}`,
      '-e',
      `MEMORY_TYPE=${memoryType}`,
      '-v',
      `${promptFilePath}:/workspace/prompt.md:ro`,
      '-v',
      `${agentResultsDir}:/workspace/results:rw`,
      '-l',
      `benchmark.agent-id=${agentConfig.agentId}`,
      '-l',
      `benchmark.arm=${agentConfig.arm}`,
      '-l',
      `benchmark.prompt-id=${agentConfig.prompt.frontmatter.id}`,
      imageTag,
    ];

    const startTime = new Date();
    let containerId: string;
    try {
      containerId = (await $`docker ${runArgs}`.quiet()).text().trim();
    } catch (error) {
      throw new Error(
        `Failed to launch container for agent ${agentConfig.agentId}: ${errorDetail(error)}`,
      );
    }

    return {
      containerId,
      agentId: agentConfig.agentId,
      arm: agentConfig.arm,
      startTime,
    };
  }

  /**
   * Returns the current status string of a container (e.g., "running", "exited").
   */
  async getContainerStatus(containerId: string): Promise<string> {
    const format = '{{.State.Status}}';
    const output = await $`docker inspect -f ${format} ${containerId}`.quiet();
    return output.text().trim();
  }

  /**
   * Builds a Docker image for the given arm (claude-mem or vanilla).
   * Uses the MEMORY_TYPE build arg to conditionally install claude-mem.
   * Build output streams to the terminal; a nonzero exit code throws.
   */
  async buildImage(
    dockerfilePath: string,
    imageName: string,
    arm: Arm,
  ): Promise<void> {
    const contextDir = resolve(dockerfilePath, '..');
    const memoryType = arm === 'claude-mem' ? 'claude-mem' : 'vanilla';
    const tag = `${imageName}:${arm}`;

    try {
      await $`docker build --build-arg MEMORY_TYPE=${memoryType} -t ${tag} ${contextDir}`;
    } catch (error) {
      throw new Error(
        `Failed to build Docker image ${tag}: ${errorDetail(error)}`,
      );
    }
  }

  /**
   * Checks if a Docker image exists locally.
   */
  async imageExists(imageTag: string): Promise<boolean> {
    const { exitCode } = await $`docker image inspect ${imageTag}`
      .quiet()
      .nothrow();
    return exitCode === 0;
  }
}

