import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { ContainerManager } from './container-manager.js';
import { loadConfig, fetchKeyUsage } from './config-env.js';
import { loadPrompts } from './prompt-loader.js';
import type {
  AgentConfig,
  Arm,
  ContainerInfo,
  Manifest,
  ManifestEntry,
} from './types.js';

const ARMS: Arm[] = ['claude-mem', 'vanilla'];
const IMAGE = 'benchmark-agent';

interface BenchmarkConfig {
  promptsDir: string;
  keysEnvPath: string;
  resultsDir: string;
  replicas: number;
  dryRun: boolean;
}

function parseConfig(): BenchmarkConfig {
  const { values } = parseArgs({
    options: {
      'prompts-dir': { type: 'string', default: './prompts' },
      'keys-env': { type: 'string', default: './keys.env' },
      'results-dir': { type: 'string', default: './results' },
      replicas: { type: 'string', default: '1' },
      'dry-run': { type: 'boolean', default: false },
    },
    strict: false,
  });

  return {
    promptsDir: values['prompts-dir'] as string,
    keysEnvPath: values['keys-env'] as string,
    resultsDir: values['results-dir'] as string,
    replicas: Number(values.replicas),
    dryRun: values['dry-run'] as boolean,
  };
}

/**
 * Generates all agent configs for the benchmark run.
 */
function generateAgentConfigs(
  prompts: Awaited<ReturnType<typeof loadPrompts>>,
  apiKey: string,
  modelVersion: string,
  replicas: number,
): AgentConfig[] {
  const configs: AgentConfig[] = [];

  for (const prompt of prompts) {
    for (let replicaIndex = 1; replicaIndex <= replicas; replicaIndex++) {
      for (const arm of ARMS) {
        const armPrefix = arm === 'claude-mem' ? 'cmem' : 'vanilla';
        configs.push({
          agentId: `${armPrefix}-${prompt.frontmatter.id}-${replicaIndex}`,
          arm,
          prompt,
          replicaIndex,
          apiKey,
          modelVersion,
        });
      }
    }
  }

  return configs;
}

/**
 * Reads the pinned claude-code version from the Dockerfile ARG so the
 * manifest records exactly what the images run (Dockerfile stays the
 * single source of truth).
 */
async function readClaudeCodeVersion(dockerfilePath: string): Promise<string> {
  const dockerfile = await readFile(dockerfilePath, 'utf8');
  const match = dockerfile.match(/^ARG CLAUDE_CODE_VERSION=(\S+)/m);
  if (!match) {
    throw new Error(
      `ARG CLAUDE_CODE_VERSION not found in ${dockerfilePath} -- the pin is required for a reproducible manifest`,
    );
  }
  return match[1]!;
}

/**
 * Builds the manifest object for the benchmark run.
 * agentConfigs and containerInfos are index-paired.
 */
function buildManifest(
  agentConfigs: AgentConfig[],
  containerInfos: ContainerInfo[],
  modelSlug: string,
  claudeCodeVersion: string,
): Manifest {
  const agents: ManifestEntry[] = agentConfigs.map((config, i) => {
    const containerInfo = containerInfos[i]!;
    return {
      agent_id: config.agentId,
      arm: config.arm,
      prompt_id: config.prompt.frontmatter.id,
      replica_index: config.replicaIndex,
      model_version: config.modelVersion,
      container_id: containerInfo.containerId,
      start_time: containerInfo.startTime.toISOString(),
    };
  });

  return {
    benchmark_version: '0.1.0',
    started_at: new Date().toISOString(),
    model_slug: modelSlug,
    claude_code_version: claudeCodeVersion,
    router: 'openrouter',
    agents,
  };
}

async function main(): Promise<void> {
  const config = parseConfig();

  console.log('Benchmark orchestrator starting');
  console.log(`  Prompts dir: ${config.promptsDir}`);
  console.log(`  Results dir: ${config.resultsDir}`);
  console.log(`  Replicas: ${config.replicas}`);
  console.log(`  Dry run: ${config.dryRun}`);

  // Load prompts
  const prompts = await loadPrompts(config.promptsDir);
  console.log(`Loaded ${prompts.length} prompts`);

  // Load the OpenRouter config (single key powers every agent + judge)
  const env = await loadConfig(config.keysEnvPath);
  console.log(`Loaded OpenRouter key, model: ${env.model}`);
  console.log(`  Judge models: ${env.judgeModels.join(', ')}`);

  // Generate agent configs
  const agentConfigs = generateAgentConfigs(
    prompts,
    env.openrouterKey,
    env.model,
    config.replicas,
  );
  console.log(
    `Generated ${agentConfigs.length} agent configs ` +
      `(${prompts.length} prompts x ${config.replicas} replicas x ${ARMS.length} arms)`,
  );

  if (config.dryRun) {
    console.log('\n--- DRY RUN: Agent configs ---');
    const dryRunOutput = agentConfigs.map((c) => ({
      agentId: c.agentId,
      arm: c.arm,
      promptId: c.prompt.frontmatter.id,
      replicaIndex: c.replicaIndex,
      modelVersion: c.modelVersion,
      // Mask the key for security
      apiKeyPrefix: c.apiKey.slice(0, 12) + '...',
    }));
    console.log(JSON.stringify(dryRunOutput, null, 2));
    return;
  }

  // Ensure results directory exists
  const absoluteResultsDir = resolve(config.resultsDir);
  await mkdir(absoluteResultsDir, { recursive: true });

  // Snapshot the key's current-UTC-day spend before launching any agents so
  // `bun run report` can compute a run-window `openrouter_billed_usd` delta
  // (GET /api/v1/key -- anti-pattern 9 rules out /activity for same-day
  // reconciliation). Best-effort: a reconciliation snapshot must never block
  // the benchmark run.
  try {
    const keyUsageStart = await fetchKeyUsage(env.openrouterKey);
    await writeFile(
      join(absoluteResultsDir, 'key-usage-start.json'),
      JSON.stringify(keyUsageStart, null, 2),
    );
    console.log(`Recorded key-usage-start.json (usage_daily=${keyUsageStart.usageDaily})`);
  } catch (error) {
    console.warn(
      `Warning: failed to record key-usage-start.json (spend reconciliation will be skipped): ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  // Build Docker images if not cached
  const dockerfilePath = join(config.promptsDir, '..', 'Dockerfile');
  const claudeCodeVersion = await readClaudeCodeVersion(dockerfilePath);
  const containerManager = new ContainerManager();
  for (const arm of ARMS) {
    const imageTag = `${IMAGE}:${arm}`;
    const alreadyExists = await containerManager.imageExists(imageTag);
    if (alreadyExists) {
      console.log(`Image ${imageTag} already exists, skipping build.`);
    } else {
      console.log(`Building image ${imageTag}...`);
      await containerManager.buildImage(dockerfilePath, IMAGE, arm);
      console.log(`Image ${imageTag} built successfully.`);
    }
  }

  // Launch containers sequentially
  const containerInfos: ContainerInfo[] = [];
  for (const agentConfig of agentConfigs) {
    const info = await containerManager.launchAgent(
      agentConfig,
      IMAGE,
      absoluteResultsDir,
    );
    containerInfos.push(info);
    console.log(
      `Launched ${info.agentId} (${containerInfos.length}/${agentConfigs.length})`,
    );
  }

  // Write manifest
  const manifest = buildManifest(
    agentConfigs,
    containerInfos,
    env.model,
    claudeCodeVersion,
  );
  const manifestPath = join(absoluteResultsDir, 'manifest.json');
  await writeFile(manifestPath, JSON.stringify(manifest, null, 2));
  console.log(`Manifest written to ${manifestPath}`);

  // Summary
  console.log('\n--- Benchmark Launch Summary ---');
  console.log(`  Total agents: ${containerInfos.length}`);
  console.log(
    `  claude-mem agents: ${containerInfos.filter((c) => c.arm === 'claude-mem').length}`,
  );
  console.log(
    `  vanilla agents: ${containerInfos.filter((c) => c.arm === 'vanilla').length}`,
  );
  console.log(`  Containers are running autonomously. Check results in: ${absoluteResultsDir}`);
}

main().catch((error: Error) => {
  console.error(`Fatal: ${error.name}: ${error.message}`);
  process.exit(1);
});

import { readFile } from 'node:fs/promises';
import { parseEnv } from 'node:util';

export const DEFAULT_MODEL = 'anthropic/claude-opus-4.6';
export const DEFAULT_JUDGE_MODELS = [
  'openai/gpt-4.1-mini',
  'google/gemini-2.5-flash-lite',
  'anthropic/claude-haiku-4.5',
];

export interface EnvConfig {
  openrouterKey: string;
  model: string;
  judgeModels: string[];
}

/**
 * Loads the OpenRouter-only config from a keys.env file.
 *
 * Contract:
 *   OPENROUTER_API_KEY  required; warns (does not fail) if the prefix
 *                       is not `sk-or-` — OpenRouter may evolve prefixes
 *   MODEL               optional OpenRouter slug, default DEFAULT_MODEL
 *   JUDGE_MODELS        optional CSV of OpenRouter slugs, default
 *                       DEFAULT_JUDGE_MODELS
 */
export async function loadConfig(keysEnvPath: string): Promise<EnvConfig> {
  const content = await readFile(keysEnvPath, 'utf-8');
  const entries = parseEnv(content) as Record<string, string>;

  const openrouterKey = entries.OPENROUTER_API_KEY?.trim();
  if (!openrouterKey) {
    throw new Error(
      `OPENROUTER_API_KEY missing or empty in ${keysEnvPath}. ` +
        'Create one at https://openrouter.ai/settings/keys',
    );
  }
  if (!openrouterKey.startsWith('sk-or-')) {
    console.warn(
      `Warning: OPENROUTER_API_KEY does not start with "sk-or-" ` +
        `(got "${openrouterKey.slice(0, 6)}..."). Proceeding anyway.`,
    );
  }

  const model = entries.MODEL?.trim() || DEFAULT_MODEL;

  const judgeModels = (entries.JUDGE_MODELS ?? '')
    .split(',')
    .map((m) => m.trim())
    .filter((m) => m.length > 0);

  return {
    openrouterKey,
    model,
    judgeModels: judgeModels.length > 0 ? judgeModels : DEFAULT_JUDGE_MODELS,
  };
}

// --- Spend reconciliation (GET /api/v1/key) ---

const OPENROUTER_KEY_URL = 'https://openrouter.ai/api/v1/key';

export interface KeyUsageSnapshot {
  fetchedAt: string;
  /** `usage_daily` from the response -- current-UTC-day spend on this key. */
  usageDaily: number;
}

/**
 * Fetches the inference key's current-UTC-day spend (`usage_daily`) for
 * run-window reconciliation deltas. Works with the inference key itself --
 * unlike the activity or `/credits` endpoints, which need a management key
 * (anti-pattern 9) and the former excludes the current day anyway.
 */
export async function fetchKeyUsage(apiKey: string): Promise<KeyUsageSnapshot> {
  const response = await fetch(OPENROUTER_KEY_URL, {
    headers: { Authorization: `Bearer ${apiKey}` },
  });
  if (!response.ok) {
    throw new Error(`Failed to fetch OpenRouter key usage: HTTP ${response.status}`);
  }
  const body = (await response.json()) as { data?: { usage_daily?: number } };
  const usageDaily = body.data?.usage_daily;
  if (typeof usageDaily !== 'number') {
    throw new Error('OpenRouter key usage response had no data.usage_daily');
  }
  return { fetchedAt: new Date().toISOString(), usageDaily };
}

