import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import type { Prompt, PromptFrontmatter } from './types.js';

/**
 * Splits a markdown file into YAML frontmatter and body content.
 * Frontmatter is delimited by `---` at the start and end.
 */
function splitFrontmatterAndBody(
  content: string,
): { rawFrontmatter: string; body: string } {
  const trimmed = content.trimStart();
  if (!trimmed.startsWith('---')) {
    throw new Error('File does not start with YAML frontmatter delimiter (---)');
  }

  // Find the closing `---` delimiter (skip the opening one)
  const closingIndex = trimmed.indexOf('---', 3);
  if (closingIndex === -1) {
    throw new Error('No closing YAML frontmatter delimiter (---) found');
  }

  const rawFrontmatter = trimmed.slice(3, closingIndex).trim();
  const body = trimmed.slice(closingIndex + 3).trim();

  return { rawFrontmatter, body };
}

/**
 * Loads all `.md` prompt files from the given directory,
 * parses their YAML frontmatter, and returns them sorted by id.
 */
export async function loadPrompts(promptsDir: string): Promise<Prompt[]> {
  const entries = await readdir(promptsDir);

  const markdownFiles = entries
    .filter((entry) => entry.endsWith('.md'))
    .sort();

  const prompts: Prompt[] = [];

  for (const fileName of markdownFiles) {
    const filePath = join(promptsDir, fileName);
    const content = await readFile(filePath, 'utf-8');

    let rawFrontmatter: string;
    let body: string;
    try {
      ({ rawFrontmatter, body } = splitFrontmatterAndBody(content));
    } catch (error) {
      throw new Error(
        `Failed to parse prompt ${filePath}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }

    let frontmatter: PromptFrontmatter;
    try {
      frontmatter = Bun.YAML.parse(rawFrontmatter) as PromptFrontmatter;
    } catch (error) {
      throw new Error(
        `Failed to parse prompt ${filePath}: Invalid YAML: ${error instanceof Error ? error.message : String(error)}`,
      );
    }

    if (!frontmatter?.id || !frontmatter?.title) {
      throw new Error(
        `Failed to parse prompt ${filePath}: frontmatter must include "id" and "title"`,
      );
    }

    prompts.push({ frontmatter, body, filePath });
  }

  // Sort by id
  prompts.sort((a, b) => a.frontmatter.id.localeCompare(b.frontmatter.id));

  return prompts;
}

