import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

// --- Interfaces ---

export interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
  cacheCreationTokens: number;
  cacheReadTokens: number;
  totalTokens: number;
}

/** Per-token USD rates for one OpenRouter model slug (GET /api/v1/models `pricing`). */
export interface ModelPricing {
  prompt: number;
  completion: number;
  input_cache_read: number;
  input_cache_write: number;
}

export type PricingTable = Record<string, ModelPricing>;

export type CostSource = 'openrouter_ledger' | 'tokens_x_live_pricing';

export interface CostResult {
  costUsd: number;
  costSource: CostSource;
}

// --- Transcript Token Parsing ---

/**
 * Parses a transcript.jsonl file and sums token usage across all assistant entries.
 *
 * Each JSONL line may contain:
 * {"type":"assistant","message":{"usage":{"input_tokens":N,"output_tokens":N,"cache_creation_input_tokens":N,"cache_read_input_tokens":N}}}
 */
export async function parseTranscriptTokens(
  transcriptPath: string,
): Promise<TokenUsage | null> {
  let content: string;
  try {
    content = await readFile(transcriptPath, 'utf-8');
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      return null;
    }
    throw new Error(
      `Failed to parse transcript at ${transcriptPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  const lines = content.split('\n').filter((line) => line.trim().length > 0);

  let inputTokens = 0;
  let outputTokens = 0;
  let cacheCreationTokens = 0;
  let cacheReadTokens = 0;

  for (const line of lines) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      // Skip malformed lines
      continue;
    }

    if (
      typeof parsed !== 'object' ||
      parsed === null ||
      (parsed as Record<string, unknown>).type !== 'assistant'
    ) {
      continue;
    }

    const message = (parsed as Record<string, unknown>).message;
    if (typeof message !== 'object' || message === null) {
      continue;
    }

    const usage = (message as Record<string, unknown>).usage;
    if (typeof usage !== 'object' || usage === null) {
      continue;
    }

    const u = usage as Record<string, unknown>;
    inputTokens += typeof u.input_tokens === 'number' ? u.input_tokens : 0;
    outputTokens += typeof u.output_tokens === 'number' ? u.output_tokens : 0;
    cacheCreationTokens +=
      typeof u.cache_creation_input_tokens === 'number'
        ? u.cache_creation_input_tokens
        : 0;
    cacheReadTokens +=
      typeof u.cache_read_input_tokens === 'number'
        ? u.cache_read_input_tokens
        : 0;
  }

  const totalTokens =
    inputTokens + outputTokens + cacheCreationTokens + cacheReadTokens;

  // If we found no usage at all, return null
  if (totalTokens === 0) {
    return null;
  }

  return {
    inputTokens,
    outputTokens,
    cacheCreationTokens,
    cacheReadTokens,
    totalTokens,
  };
}

// --- Live Pricing (GET /api/v1/models -- public, no key required) ---

const OPENROUTER_MODELS_URL = 'https://openrouter.ai/api/v1/models';
const MODELS_SNAPSHOT_FILENAME = 'models-snapshot.json';

interface OpenRouterModelEntry {
  id?: string;
  pricing?: {
    prompt?: string;
    completion?: string;
    input_cache_read?: string;
    input_cache_write?: string;
  };
}

/**
 * Fetches live per-token pricing for every OpenRouter model and indexes it
 * by slug. Public endpoint (Phase 0 table) -- no API key required.
 */
export async function fetchPricing(): Promise<PricingTable> {
  const response = await fetch(OPENROUTER_MODELS_URL);
  if (!response.ok) {
    throw new Error(
      `Failed to fetch OpenRouter model pricing: HTTP ${response.status}`,
    );
  }

  const body = (await response.json()) as { data?: OpenRouterModelEntry[] };
  const table: PricingTable = {};
  for (const model of body.data ?? []) {
    if (!model.id || !model.pricing) continue;
    table[model.id] = {
      prompt: Number(model.pricing.prompt ?? 0),
      completion: Number(model.pricing.completion ?? 0),
      input_cache_read: Number(model.pricing.input_cache_read ?? 0),
      input_cache_write: Number(model.pricing.input_cache_write ?? 0),
    };
  }
  return table;
}

/**
 * Fetches live pricing and snapshots the raw table to
 * `<resultsDir>/models-snapshot.json` for reproducibility.
 */
export async function snapshotPricing(resultsDir: string): Promise<PricingTable> {
  const table = await fetchPricing();
  await mkdir(resultsDir, { recursive: true });
  await writeFile(
    join(resultsDir, MODELS_SNAPSHOT_FILENAME),
    JSON.stringify(table, null, 2),
  );
  return table;
}

/**
 * Reuses a previously-written `models-snapshot.json` when present -- keeps a
 * report reproducible across re-runs and lets fixture/test runs inject
 * pricing without hitting the network. Fetches live (and snapshots) only
 * when no cached file exists yet.
 */
export async function loadOrFetchPricing(resultsDir: string): Promise<PricingTable> {
  try {
    const cached = await readFile(
      join(resultsDir, MODELS_SNAPSHOT_FILENAME),
      'utf-8',
    );
    return JSON.parse(cached) as PricingTable;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
  }
  return snapshotPricing(resultsDir);
}

/**
 * Looks up per-token rates for a slug, tolerating OpenRouter's
 * served-vs-requested slug mismatch (Phase 4 smoke findings): a concrete
 * dated variant such as `anthropic/claude-4.6-opus-20260205` never appears
 * in `/models`, which only lists the requested alias
 * (`anthropic/claude-opus-4.6`). `priceTokens` is always called with the
 * *requested* slug (`aggregateAgent`'s `modelVersion`), so this rarely
 * bites in practice, but stripping a trailing `-YYYYMMDD` suffix is a
 * cheap, harmless safety net against a future caller passing a served slug.
 */
function resolveRates(slug: string, pricing: PricingTable): ModelPricing | undefined {
  if (pricing[slug]) return pricing[slug];
  const stripped = slug.replace(/-\d{8}$/, '');
  if (stripped !== slug && pricing[stripped]) return pricing[stripped];
  return undefined;
}

/**
 * Prices a summed token usage at a specific model slug's live per-token
 * rates. An unpriced slug (missing from the table) prices at 0 -- callers
 * surface this via `cost_source` rather than throwing mid-report.
 */
export function priceTokens(
  usage: TokenUsage,
  slug: string,
  pricing: PricingTable,
): number {
  const rates = resolveRates(slug, pricing);
  if (!rates) return 0;

  return (
    usage.inputTokens * rates.prompt +
    usage.outputTokens * rates.completion +
    usage.cacheReadTokens * rates.input_cache_read +
    usage.cacheCreationTokens * rates.input_cache_write
  );
}

// --- Exact OpenRouter-Ledger Costing ---
//
// Per the Phase 4 smoke findings (plans/01-smoke-findings.md):
//   - Claude Code's OpenRouter-routed transcripts do NOT carry a
//     `message.usage.cost` field today (checked first below anyway, so the
//     exact-ledger path activates for free the moment that changes).
//   - They DO carry the OpenRouter generation id directly in `message.id`
//     (`gen-...`), which resolves on GET /api/v1/generation and returns
//     `total_cost`. The findings' verdict: "GO on exact-ledger costing" --
//     sum `total_cost` over the unique `message.id` values per transcript.
//   - Claude Code's own `total_cost_usd` / `modelUsage.costUSD` are WRONG
//     under OpenRouter (priced at Anthropic-direct rates, ~3x the actual
//     OpenRouter bill) -- never used here.

const OPENROUTER_GENERATION_URL = 'https://openrouter.ai/api/v1/generation';
const LEDGER_MAX_ATTEMPTS = 3;
const LEDGER_RETRY_BACKOFF_MS = [1_000, 4_000];

/**
 * Scans assistant transcript lines for a `usage.cost` field and sums it
 * when present; returns null when the field never appears.
 */
function sumInlineLedgerCost(
  lines: string[],
): number | null {
  let total = 0;
  let found = false;

  for (const line of lines) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      continue;
    }
    if (
      typeof parsed !== 'object' ||
      parsed === null ||
      (parsed as Record<string, unknown>).type !== 'assistant'
    ) {
      continue;
    }
    const message = (parsed as Record<string, unknown>).message;
    if (typeof message !== 'object' || message === null) continue;
    const usage = (message as Record<string, unknown>).usage;
    if (typeof usage !== 'object' || usage === null) continue;
    const cost = (usage as Record<string, unknown>).cost;
    if (typeof cost === 'number') {
      total += cost;
      found = true;
    }
  }

  return found ? total : null;
}

/**
 * Collects the unique OpenRouter generation ids (`message.id`, format
 * `gen-...`) from every assistant line in a transcript. Dedupe by id (not
 * by line): Claude Code can re-emit the same generation id across the
 * lines belonging to one API response, so summing per-line would double
 * count.
 */
function collectGenerationIds(lines: string[]): string[] {
  const ids = new Set<string>();

  for (const line of lines) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      continue;
    }
    if (
      typeof parsed !== 'object' ||
      parsed === null ||
      (parsed as Record<string, unknown>).type !== 'assistant'
    ) {
      continue;
    }
    const message = (parsed as Record<string, unknown>).message;
    if (typeof message !== 'object' || message === null) continue;
    const id = (message as Record<string, unknown>).id;
    if (typeof id === 'string' && id.startsWith('gen-')) {
      ids.add(id);
    }
  }

  return [...ids];
}

/**
 * Looks up the exact billed cost of one generation id via GET
 * /api/v1/generation. Retries transient failures/429s (3 attempts, 1s/4s
 * backoff, honoring `retry-after`) -- mirrors the judge's `callOpenRouter`.
 */
export async function fetchGenerationCost(
  generationId: string,
  apiKey: string,
): Promise<number> {
  let lastError: unknown;

  for (let attempt = 0; attempt < LEDGER_MAX_ATTEMPTS; attempt++) {
    try {
      const response = await fetch(
        `${OPENROUTER_GENERATION_URL}?id=${encodeURIComponent(generationId)}`,
        { headers: { Authorization: `Bearer ${apiKey}` } },
      );

      if (response.status === 429) {
        const retryAfterSeconds = parseInt(
          response.headers.get('retry-after') ?? '',
          10,
        );
        const error = new Error(
          `OpenRouter generation lookup rate limited (429) for ${generationId}`,
        );
        if (!isNaN(retryAfterSeconds) && retryAfterSeconds >= 0) {
          (error as Error & { retryAfterMs?: number }).retryAfterMs =
            retryAfterSeconds * 1000;
        }
        throw error;
      }

      if (!response.ok) {
        throw new Error(
          `OpenRouter generation lookup for ${generationId} returned HTTP ${response.status}`,
        );
      }

      const body = (await response.json()) as {
        data?: { total_cost?: number };
        total_cost?: number;
      };
      const totalCost = body.data?.total_cost ?? body.total_cost;
      if (typeof totalCost !== 'number') {
        throw new Error(
          `OpenRouter generation lookup for ${generationId} had no total_cost`,
        );
      }
      return totalCost;
    } catch (error) {
      lastError = error;
      if (attempt === LEDGER_MAX_ATTEMPTS - 1) break;
      const retryAfterMs = (error as { retryAfterMs?: number }).retryAfterMs;
      const delayMs = retryAfterMs ?? LEDGER_RETRY_BACKOFF_MS[attempt];
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }

  throw lastError;
}

export interface ComputeAgentCostOptions {
  transcriptPath: string;
  usage: TokenUsage | null;
  modelSlug: string;
  pricing: PricingTable;
  /** When provided, attempt exact per-generation ledger costing first. */
  apiKey?: string;
}

/**
 * Computes one agent's cost, preferring exactness over estimation:
 *   1. Inline `usage.cost` summed straight from the transcript, if present.
 *   2. Exact `total_cost` summed over unique OpenRouter generation ids via
 *      GET /api/v1/generation, if an API key was supplied and lookups
 *      succeed (the Phase 4 smoke-findings path).
 *   3. Token x live-pricing fallback (`priceTokens`) -- always available,
 *      zero network calls, the only path exercised in tests.
 * A partial ledger sum is never mixed with the fallback: if step 2 starts
 * but any lookup fails, the whole run falls through to step 3.
 */
export async function computeAgentCost(
  options: ComputeAgentCostOptions,
): Promise<CostResult> {
  const { transcriptPath, usage, modelSlug, pricing, apiKey } = options;

  let content: string | null = null;
  try {
    content = await readFile(transcriptPath, 'utf-8');
  } catch {
    content = null;
  }

  if (content !== null) {
    const lines = content.split('\n').filter((line) => line.trim().length > 0);

    const inlineCost = sumInlineLedgerCost(lines);
    if (inlineCost !== null) {
      return { costUsd: inlineCost, costSource: 'openrouter_ledger' };
    }

    if (apiKey) {
      const generationIds = collectGenerationIds(lines);
      if (generationIds.length > 0) {
        try {
          let total = 0;
          for (const id of generationIds) {
            total += await fetchGenerationCost(id, apiKey);
          }
          return { costUsd: total, costSource: 'openrouter_ledger' };
        } catch {
          // Fall through to the token x live-pricing fallback below.
        }
      }
    }
  }

  const costUsd = usage ? priceTokens(usage, modelSlug, pricing) : 0;
  return { costUsd, costSource: 'tokens_x_live_pricing' };
}

